"use client";

import styles from "./style.module.scss";
import "../../../../containers/Career/style.scss";

interface TimelineItem {
  title: string;
  company: string;
  location: string;
  period: string;
  side: "left" | "right";
  color: string;
  isStudy?: boolean;
}

const timelineItems: TimelineItem[] = [
  {
    title: "Senior Software Engineer",
    company: "Pasha Insurance",
    location: "Baku, Azerbaijan",
    period: "12/2024 – Present",
    side: "right",
    color: "neonBlue",
  },
  {
    title: "Senior Frontend Engineer",
    company: "Machinarium",
    location: "Istanbul, Turkey",
    period: "11/2023 – 12/2024",
    side: "left",
    color: "brightOrange",
  },
  {
    title: "Software Instructor",
    company: "Code Academy",
    location: "Baku, Azerbaijan",
    period: "10/2022 – 12/2024",
    side: "right",
    color: "deadBlue",
  },
  {
    title: "Frontend Engineer",
    company: "Vitanur",
    location: "Boston, USA",
    period: "04/2023 – 11/2023",
    side: "left",
    color: "deadGreen",
  },
  {
    title: "B.Sc. — IT & Systems Engineering",
    company: "Azerbaijan State Oil and Industry University",
    location: "Baku, Azerbaijan",
    period: "09/2010 – 05/2014",
    side: "left",
    color: "deadOrange",
    isStudy: true,
  },
];

const animClasses = ["six", "five", "four", "three", "one"];

const CareerTimeline = () => {
  return (
    <div className={styles["timeline-side"]}>
      <div className="career">
        <section className="design-section">
          <div className="timeline">
            {timelineItems.map((item, index) => {
              const isFirst = index === 0;
              const isLast = index === timelineItems.length - 1;
              const animClass = animClasses[index] ?? `item-${index}`;
              const middleClass = isFirst ? "top" : isLast ? "bottom" : "";

              const middleEl = (
                <div className={`timeline-middle ${middleClass}`.trim()}>
                  {!isFirst && <div className="timeline-circle"></div>}
                </div>
              );

              const contentEl = (
                <div
                  className={`timeline-component timeline-content${item.isStudy ? " study" : ""} animated animatedFadeInUp fadeInUp ${animClass}`}
                  style={
                    isLast ? { paddingTop: 0, paddingBottom: 0 } : undefined
                  }
                >
                  {item.side === "left" ? (
                    <>
                      <div className="textCareer text-right">
                        <h3>{item.title}</h3>
                        <p>{item.company}</p>
                        <p>{item.location}</p>
                        <p>{item.period}</p>
                      </div>
                      <div className={`lineCardCareer ${item.color}`}></div>
                    </>
                  ) : (
                    <>
                      <div className={`lineCardCareer ${item.color}`}></div>
                      <div className="textCareer">
                        <h3>{item.title}</h3>
                        <p>{item.company}</p>
                        <p>{item.location}</p>
                        <p>{item.period}</p>
                      </div>
                    </>
                  )}
                </div>
              );

              return item.side === "right" ? (
                <div
                  key={index}
                  className="timeline-row-right"
                  style={{ display: "contents" }}
                >
                  <div className="timeline-empty"></div>
                  {middleEl}
                  {contentEl}
                </div>
              ) : (
                <div
                  key={index}
                  className="timeline-row-left"
                  style={{ display: "contents" }}
                >
                  {contentEl}
                  {middleEl}
                  <div className="timeline-empty"></div>
                </div>
              );
            })}
          </div>
        </section>
      </div>
    </div>
  );
};

export default CareerTimeline;
